      "def dijkstra(graph, start, goal):\n    dist = {start: 0}\n    done = []\n    while True:\n        current = None\n        for node in dist:\n            if node not in done and (current is None or dist[node] < dist[current]):\n                current = node\n        if current is None:\n            return -1\n        if current == goal:\n            return dist[current]\n        done.append(current)\n        for nxt in graph[current]:\n            d = dist[current] + graph[current][nxt]\n            if nxt not in dist or d < dist[nxt]:\n                dist[nxt] = d\n",
